    def create_order(self, symbol: str, type: OrderType, side: OrderSide, amount: float, price: Num = None, params={}) -> Order:
        """
        create a swap order on ChangeNOW(requires API key)

        https://changenow.io/api/docs

        :param str symbol: unified market symbol, e.g. 'BTC/ETH'
        :param str type: order type – only 'market' is supported(floating rate), or 'limit' for fixed-rate
        :param str side: 'buy' or 'sell' – for swaps self is always 'sell'(sell base for quote)
        :param float amount: amount of the base currency to send
        :param float [price]: not used for ChangeNOW standard flow
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param str params['address']: destination address for the quote currency(required)
        :param str [params.extraId]: extra id or memo for the destination address(e.g. for XRP, XLM)
        :param str [params.refundAddress]: refund address for the base currency
        :param str [params.refundExtraId]: extra id or memo for the refund address
        :param str [params.rateId]: rate id from fixed-rate estimate(required for fixed-rate)
        :param str [params.contactEmail]: contact email for notifications
        :returns dict: an `order structure <https://docs.ccxt.com/?id=order-structure>`
        """
        self.check_required_credentials()
        self.load_markets()
        market = self.market(symbol)
        baseId = self.safe_string(market, 'baseId')
        quoteId = self.safe_string(market, 'quoteId')
        address = self.safe_string(params, 'address')
        if address is None:
            raise ArgumentsRequired(self.id + ' createOrder() requires params.address – the destination address for the received currency')
        request: dict = {
            'apiKey': self.apiKey,
            'from': baseId,
            'to': quoteId,
            'amount': self.number_to_string(amount),
            'address': address,
        }
        extraId = self.safe_string(params, 'extraId')
        if extraId is not None:
            request['extraId'] = extraId
        refundAddress = self.safe_string(params, 'refundAddress')
        if refundAddress is not None:
            request['refundAddress'] = refundAddress
        refundExtraId = self.safe_string(params, 'refundExtraId')
        if refundExtraId is not None:
            request['refundExtraId'] = refundExtraId
        rateId = self.safe_string(params, 'rateId')
        if rateId is not None:
            request['rateId'] = rateId
        contactEmail = self.safe_string(params, 'contactEmail')
        if contactEmail is not None:
            request['contactEmail'] = contactEmail
        params = self.omit(params, ['address', 'extraId', 'refundAddress', 'refundExtraId', 'rateId', 'contactEmail'])
        response = self.privatePostTransactionsApiKey(self.extend(request, params))
        #
        #  {
        #      "id": "5788c1ab245b37",
        #      "payinAddress": "3NWnMcW31...",
        #      "payoutAddress": "0x0000...",
        #      "fromCurrency": "btc",
        #      "toCurrency": "eth",
        #      "amount": "0.3233127",       # estimated receive amount(quote)
        #      "directedAmount": "0.01"      # amount sent(base)
        #  }
        #
        return self.parse_order(response, market)

    def fetch_order(self, id: str, symbol: Str = None, params={}) -> Order:
        """
        fetch the status of a ChangeNOW exchange/swap order

        https://changenow.io/api/docs

        :param str id: the order / transaction id
        :param str [symbol]: unified market symbol(optional)
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: an `order structure <https://docs.ccxt.com/?id=order-structure>`
        """
        self.check_required_credentials()
        request: dict = {
            'id': id,
            'apiKey': self.apiKey,
        }
        response = self.privateGetTransactionsIdApiKey(self.extend(request, params))
        #
        #  {
        #      "status": "finished",
        #      "payinHash": "0x...",
        #      "payoutHash": "0x...",
        #      "payinAddress": "0xAB5...",
        #      "payoutAddress": "1Jqf...",
        #      "fromCurrency": "eth",
        #      "toCurrency": "btc",
        #      "amountSend": 1,
        #      "amountReceive": 0.07365102,
        #      "networkFee": "0.0005",
        #      "id": "a5c73e2603f40d",
        #      "updatedAt": "2023-01-15T12:34:56.789Z",
        #      "createdAt": "2023-01-15T12:30:00.000Z",
        #      "expectedSendAmount": 1,
        #      "expectedReceiveAmount": 0.07365102
        #  }
        #
        return self.parse_order(response)

    def parse_order(self, order: dict, market: Market = None) -> Order:
        id = self.safe_string(order, 'id')
        fromCurrency = self.safe_string(order, 'fromCurrency')
        toCurrency = self.safe_string(order, 'toCurrency')
        parsedSymbol = None
        if fromCurrency is not None and toCurrency is not None:
            baseCode = self.safe_currency_code(fromCurrency)
            quoteCode = self.safe_currency_code(toCurrency)
            parsedSymbol = baseCode + '/' + quoteCode
        symbol = self.safe_symbol(None, market)
        if symbol is None:
            symbol = parsedSymbol
        rawStatus = self.safe_string(order, 'status')
        status = None
        if rawStatus is not None:
            status = self.parse_order_status(rawStatus)
        else:
            # v1 create response has no status — default to 'open'
            status = 'open'
        # v1 fetch response uses amountSend/expectedSendAmount
        # v1 create response uses directedAmount(amount sent) and amount(estimated receive)
        amountSend = self.safe_string_2(order, 'amountSend', 'expectedSendAmount')
        directedAmount = self.safe_string(order, 'directedAmount')
        amountReceive = self.safe_string_2(order, 'amountReceive', 'expectedReceiveAmount')
        orderAmount = amountSend
        if orderAmount is None:
            orderAmount = directedAmount
        orderPrice = amountReceive
        if orderPrice is None and directedAmount is not None:
            # v1 create response: 'amount' is estimated receive, not send amount
            orderPrice = self.safe_string(order, 'amount')
        if orderAmount is None and directedAmount is None:
            # Use raw amount only when directedAmount is missing; otherwise amount may mean estimated receive.
            orderAmount = self.safe_string(order, 'amount')
        createdAt = self.safe_string(order, 'createdAt')
        updatedAt = self.safe_string(order, 'updatedAt')
        timestamp = self.parse8601(createdAt)
        lastUpdateTimestamp = self.parse8601(updatedAt)
        networkFee = self.safe_string(order, 'networkFee')
        return self.safe_order({
            'id': id,
            'clientOrderId': None,
            'info': order,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'lastTradeTimestamp': None,
            'lastUpdateTimestamp': lastUpdateTimestamp,
            'symbol': symbol,
            'type': 'market',
            'timeInForce': None,
            'postOnly': None,
            'side': 'sell',
            'price': orderPrice,
            'stopPrice': None,
            'triggerPrice': None,
            'amount': orderAmount,
            'cost': None,
            'average': None,
            'filled': None,
            'remaining': None,
            'status': status,
            'fee': {
                'currency': None,
                'cost': networkFee,
                'rate': None,
            },
            'trades': None,
        }, market)

    def parse_order_status(self, status: Str) -> Str:
        statuses: dict = self.safe_dict(self.options, 'statusMapping', {})
        return self.safe_string(statuses, status, status)

    def sign(self, path, api='public', method='GET', params={}, headers=None, body=None):
        url = self.urls['api']['rest'] + '/' + self.implode_params(path, params)
        query = self.omit(params, self.extract_params(path))
        if method == 'GET':
            if query:
                url += '?' + self.urlencode(query)
        elif method == 'POST':
            if query:
                body = self.json(query)
                headers = {
                    'Content-Type': 'application/json',
                }
        return {'url': url, 'method': method, 'body': body, 'headers': headers}

    def handle_errors(self, httpCode: int, reason: str, url: str, method: str, headers: dict, body: str, response, requestHeaders, requestBody):
        if httpCode == 404 and url.find('/transactions/') >= 0:
            raise OrderNotFound(self.id + ' order not found')
        if response is None:
            return None
        #
        # error responses from ChangeNOW:
        #  {"error": "pair_is_inactive", "message": "This pair is currently unavailable"}
        #  {"error": "not_valid_params", "message": "Invalid request parameters"}
        #  {"error": "deposit_too_small", "message": "Deposit amount is less than minimum"}
        #  {"message": "Unauthorized"}
        #
        error = self.safe_string(response, 'error')
        message = self.safe_string(response, 'message')
        if error is not None:
            if error == 'not_valid_params':
                raise BadRequest(self.id + ' ' + body)
            if error == 'unauthorized':
                raise AuthenticationError(self.id + ' ' + body)
            if error == 'not_found':
                raise OrderNotFound(self.id + ' ' + body)
            raise ExchangeError(self.id + ' ' + body)
        if message is not None and httpCode >= 400:
            if httpCode == 401 or httpCode == 403:
                raise AuthenticationError(self.id + ' ' + body)
            raise BadRequest(self.id + ' ' + body)
        return None
